        <div class="lg:sticky lg:top-20 lg:self-start"><x-card><h2 class="font-heading text-base font-bold text-slate-900 dark:text-white">Your Order</h2><p class="mt-1 text-xs text-slate-400">Click a product to add it. Adjust quantities below.</p><div x-show="cart.length === 0" class="py-10 text-center"><x-icon name="cart" class="mx-auto size-10 text-slate-300" /><p class="mt-3 text-sm text-slate-400">Your cart is empty</p></div><div x-show="cart.length > 0" x-cloak class="mt-4 space-y-3"><template x-for="(item, index) in cart" :key="item.product_id"><div class="border-b border-slate-100 pb-3 dark:border-white/5"><div class="flex items-start justify-between gap-2"><div class="min-w-0"><p class="truncate text-sm font-medium text-slate-900 dark:text-white" x-text="item.name + ' (' + item.size + ')'" ></p><p class="font-mono text-xs text-slate-400" x-text="'₱' + Number(item.unit_price).toFixed(2) + ' each'"></p></div><button type="button" x-on:click="removeFromCart(index)" class="text-slate-400 hover:text-danger-600" aria-label="Remove product"><x-icon name="trash" class="size-4" /></button></div><div class="mt-2 flex items-center justify-between"><div class="flex items-center gap-2"><button type="button" x-on:click="decrement(index)" class="flex size-7 items-center justify-center rounded-full bg-slate-100 dark:bg-white/10" aria-label="Decrease quantity"><span class="block h-0.5 w-3 bg-current" aria-hidden="true"></span></button><span class="w-6 text-center text-sm font-semibold" x-text="item.quantity"></span><button type="button" x-on:click="increment(index)" class="flex size-7 items-center justify-center rounded-full bg-slate-100 text-slate-600 transition hover:bg-slate-200 dark:bg-white/10 dark:text-slate-300" aria-label="Increase quantity"><x-icon name="plus" class="size-3.5" /></button></div><span class="font-mono text-sm font-semibold" x-text="'₱' + itemTotal(item).toFixed(2)"></span></div><input type="hidden" :name="'items[' + index + '][product_id]'" :value="item.product_id"><input type="hidden" :name="'items[' + index + '][quantity]'" :value="item.quantity"></div></template><div class="flex items-center justify-between pt-2 text-base font-bold"><span>Total</span><span class="font-mono text-primary-600" x-text="'₱' + subtotal.toFixed(2)"></span></div></div><div class="mt-5 space-y-4 border-t border-slate-100 pt-5 dark:border-white/10"><div><x-input-label for="customer_address" value="Delivery address" /><x-textarea id="customer_address" name="customer_address" class="mt-1" required>{{ old('customer_address', auth()->user()->address) }}</x-textarea></div><div><x-input-label for="preferred_delivery_date" value="Preferred delivery date (optional)" /><x-text-input id="preferred_delivery_date" type="date" name="preferred_delivery_date" class="mt-1" :value="old('preferred_delivery_date')" data-flatpickr /></div><div><x-input-label for="notes" value="Order notes (optional)" /><x-textarea id="notes" name="notes" class="mt-1">{{ old('notes') }}</x-textarea></div><x-button type="submit" class="w-full" x-bind:disabled="cart.length === 0">Place Order</x-button></div></x-card></div>
