    @push('scripts')<script>function customerOrder(products, oldItems) { return { products, search: '', cart: oldItems.length ? oldItems.map(item => { const p = products.find(product => String(product.id) === String(item.product_id)); return p ? { ...p, quantity: Number(item.quantity || 1) } : null; }).filter(Boolean) : [], get filteredProducts() { const term = this.search.toLowerCase(); return this.products.filter(p => !term || (p.name + ' ' + p.size).toLowerCase().includes(term)); }, addToCart(product) { const existing = this.cart.find(item => item.product_id === product.id); if (existing) { if (existing.quantity < product.stock_quantity) existing.quantity++; } else this.cart.push({ ...product, quantity: 1 }); }, removeFromCart(index) { this.cart.splice(index, 1); }, increment(index) { if (this.cart[index].quantity < this.cart[index].stock_quantity) this.cart[index].quantity++; }, decrement(index) { if (this.cart[index].quantity > 1) this.cart[index].quantity--; }, itemTotal(item) { return Number(item.unit_price) * item.quantity; }, get subtotal() { return this.cart.reduce((sum, item) => sum + this.itemTotal(item), 0); } }; }</script>@endpush
